css:
:root {
  --bg-warm: #faf7f2;
  --card-bg: #ffffff;
  --text-primary: #3a3632;
  --text-secondary: #8a837a;
  --accent: #d49c62;
  --accent-hover: #c08a54;
  --accent-light: #f5e6d0;
  --border: #e8e0d6;
  --success: #6a9e6f;
  --bar-bg: #e8e0d6;
  --radius: 12px;
  --shadow: 0 2px 8px rgba(58, 54, 50, 0.06);
}

.earbud-console {
  font-family: -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
  background: var(--bg-warm);
  color: var(--text-primary);
  max-width: 420px;
  margin: 0 auto;
  padding: 20px 16px 24px;
  border-radius: var(--radius);
  box-sizing: border-box;
}

.console-header {
  text-align: center;
  margin-bottom: 20px;
}

.console-header h2 {
  margin: 0 0 4px;
  font-size: 1.35rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.subtitle {
  margin: 0;
  font-size: 0.85rem;
  color: var(--text-secondary);
}

h3 {
  margin: 0 0 10px;
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.battery-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 12px;
}

.battery-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 12px 8px;
  text-align: center;
  box-shadow: var(--shadow);
}

.battery-label {
  display: block;
  font-size: 0.8rem;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.battery-value {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text-primary);
}

.battery-unit {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-left: 2px;
}

.battery-bar {
  height: 6px;
  background: var(--bar-bg);
  border-radius: 3px;
  margin-top: 8px;
  overflow: hidden;
}

.battery-fill {
  height: 100%;
  width: 0%;
  background: var(--accent);
  border-radius: 3px;
  transition: width 0.4s ease;
}

.refresh-btn {
  width: 100%;
  padding: 10px;
  background: var(--accent-light);
  color: var(--accent-hover);
  border: none;
  border-radius: var(--radius);
  font-size: 0.9rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s;
}

.refresh-btn:hover {
  background: var(--accent);
  color: #fff;
}

.noise-section {
  margin: 20px 0;
}

.noise-buttons {
  display: flex;
  gap: 8px;
  margin-bottom: 10px;
}

.noise-btn {
  flex: 1;
  padding: 10px 4px;
  background: var(--card-bg);
  color: var(--text-primary);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  font-size: 0.85rem;
  cursor: pointer;
  transition: all 0.2s;
}

.noise-btn:hover {
  border-color: var(--accent);
  background: var(--accent-light);
}

.noise-btn.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.current-mode {
  margin: 0;
  font-size: 0.8rem;
  color: var(--text-secondary);
  text-align: center;
}

.volume-section {
  margin: 20px 0 16px;
}

.volume-control {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 10px;
}

#volume-slider {
  flex: 1;
  height: 6px;
  -webkit-appearance: none;
  appearance: none;
  background: var(--bar-bg);
  border-radius: 3px;
  outline: none;
}

#volume-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
  box-shadow: 0 1px 4px rgba(0,0,0,0.15);
}

.volume-display {
  min-width: 48px;
  text-align: right;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
}

.volume-actions {
  display: flex;
  gap: 8px;
}

.vol-btn {
  flex: 1;
  padding: 9px;
  background: var(--card-bg);
  color: var(--text-primary);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  font-size: 0.85rem;
  cursor: pointer;
  transition: all 0.2s;
}

.vol-btn:hover {
  border-color: var(--accent);
  background: var(--accent-light);
}

.status-bar {
  margin-top: 16px;
  padding: 8px 12px;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 0.8rem;
  color: var(--text-secondary);
  text-align: center;
  min-height: 20px;
}

.status-bar.error {
  color: #c0392b;
  border-color: #f5c6cb;
  background: #fff5f5;
}

.status-bar.success {
  color: var(--success);
  border-color: #c3e6cb;
  background: #f0fff0;
}

javascript:
(function() {
  const statusBar = document.getElementById('status-bar');
  const leftValue = document.getElementById('left-value');
  const rightValue = document.getElementById('right-value');
  const caseValue = document.getElementById('case-value');
  const leftFill = document.getElementById('left-fill');
  const rightFill = document.getElementById('right-fill');
  const caseFill = document.getElementById('case-fill');
  const currentModeEl = document.getElementById('current-mode');
  const volumeSlider = document.getElementById('volume-slider');
  const volumeDisplay = document.getElementById('volume-display');
  const btnRefresh = document.getElementById('btn-refresh');
  const btnReadVolume = document.getElementById('btn-read-volume');
  const btnSetVolume = document.getElementById('btn-set-volume');
  const noiseButtons = document.querySelectorAll('.noise-btn');

  const modeLabels = {
    off: '关闭降噪',
    light: '轻度降噪',
    balanced: '均衡降噪'
  };

  function setStatus(msg, type) {
    statusBar.textContent = msg;
    statusBar.className = 'status-bar' + (type ? ' ' + type : '');
  }

  function updateBatteryUI(battery) {
    const items = [
      { val: battery.left, el: leftValue, fill: leftFill },
      { val: battery.right, el: rightValue, fill: rightFill },
      { val: battery.case, el: caseValue, fill: caseFill }
    ];
    items.forEach(function(item) {
      if (item.val === null || item.val === undefined) {
        item.el.textContent = '—';
        item.fill.style.width = '0%';
      } else {
        const pct = Math.max(0, Math.min(100, item.val));
        item.el.textContent = pct;
        item.fill.style.width = pct + '%';
        if (pct <= 20) {
          item.fill.style.background = '#c0392b';
        } else if (pct <= 50) {
          item.fill.style.background = '#d49c62';
        } else {
          item.fill.style.background = '#6a9e6f';
        }
      }
    });
  }

  function updateNoiseUI(mode) {
    noiseButtons.forEach(function(btn) {
      if (btn.dataset.mode === mode) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
    });
    currentModeEl.textContent = modeLabels[mode] || '当前：' + mode;
  }

  async function readState() {
    try {
      setStatus('正在读取电量…', '');
      const result = await window.wujian.request('read_state', {});
      updateBatteryUI(result.state.battery);
      updateNoiseUI(result.state.noise_mode);
      setStatus('电量已刷新', 'success');
    } catch (e) {
      setStatus('读取失败：' + e.message, 'error');
    }
  }

  async function setNoiseMode(mode) {
    try {
      setStatus('切换至' + (modeLabels[mode] || mode) + '…', '');
      await window.wujian.request('set_noise_mode', { mode: mode });
      updateNoiseUI(mode);
      setStatus('降噪已切换：' + (modeLabels[mode] || mode), 'success');
    } catch (e) {
      setStatus('切换失败：' + e.message, 'error');
    }
  }

  async function readVolume() {
    try {
      setStatus('正在读取音量…', '');
      const result = await window.wujian.request('read_volume', {});
      const vol = result.state.volume;
      volumeSlider.value = vol;
      volumeDisplay.textContent = vol + '%';
      setStatus('音量已读取：' + vol + '%', 'success');
    } catch (e) {
      setStatus('读取音量失败：' + e.message, 'error');
    }
  }

  async function setVolume() {
    const level = parseInt(volumeSlider.value, 10);
    try {
      setStatus('正在设置音量至' + level + '%…', '');
      await window.wujian.request('set_volume', { level: level });
      volumeDisplay.textContent = level + '%';
      setStatus('音量已设为' + level + '%', 'success');
    } catch (e) {
      setStatus('设置音量失败：' + e.message, 'error');
    }
  }

  // Event bindings
  btnRefresh.addEventListener('click', readState);
  btnReadVolume.addEventListener('click', readVolume);
  btnSetVolume.addEventListener('click', setVolume);

  noiseButtons.forEach(function(btn) {
    btn.addEventListener('click', function() {
      setNoiseMode(btn.dataset.mode);
    });
  });

  volumeSlider.addEventListener('input', function() {
    volumeDisplay.textContent = volumeSlider.value + '%';
  });

  // Initial load
  readState();
  readVolume();
})();
